SELECT o.status, DATE_FORMAT(o.order_date, 'yyyy-MM') AS order_month, MAX(p.amount) - MIN(p.amount) AS amount_range, ROUND(STDDEV(p.amount), 2) AS stddev_amount FROM payments p FULL OUTER JOIN orders o ON p.order_id = o.id INNER JOIN customers c ON o.customer_id = c.id GROUP BY o.status, DATE_FORMAT(o.order_date, 'yyyy-MM') ORDER BY order_month;
